const event = $json;
if (event.executionStatus !== 'RUNNING') throw new Error('Execution is not RUNNING');
if (event.enrollmentStatus !== 'ACTIVE') throw new Error('Enrollment is not ACTIVE');
if (!event.attempt || !Number.isInteger(event.attempt) || event.attempt < 1) throw new Error('Invalid attempt number');
if (!Number.isInteger(event.maxRetries) || event.maxRetries < 0) throw new Error('Invalid retry limit');
return { json: { ...event, contextVerified: true } };

const data = $input.first().json;
if (typeof data.recipient !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.recipient)) throw new Error('Invalid recipient email');
if (typeof data.subject !== 'string' || !data.subject.trim()) throw new Error('Missing subject');
if (typeof data.message !== 'string' || !data.message.trim()) throw new Error('Missing message');
const html = data.message.replace(/\n/g, '<br/>');
return [{ json: { ...data, recipientEmail: data.recipient, emailSubject: data.subject, emailHtml: html, templateValid: true, messageBuiltAt: new Date().toISOString() } }];

const result = $input.first().json;
const prev = $('5. Build Approved Message').first().json;
const success = result.success === true;
const retryable = result.retryable === true;
const finalAttempt = prev.attempt > prev.maxRetries;
const finalFailure = !success && (!retryable || finalAttempt);
const deliveryStatus = success ? 'SUCCESS' : finalFailure ? (prev.ownerId ? 'FINAL_ERROR' : 'FINAL_ERROR_NO_OWNER') : 'RETRYABLE_ERROR';
return [{ json: {
  executionId: prev.executionId,
  enrollmentId: prev.enrollmentId,
  stepId: prev.stepId,
  workflowRunId: prev.workflowRunId,
  correlationId: prev.correlationId,
  ownerId: prev.ownerId,
  attempt: prev.attempt,
  deliveryStatus,
  retryable: !success && retryable && !finalAttempt,
  providerMessageId: result.providerMessageId ?? null,
  simulated: result.simulated === true,
  normalizedAt: new Date().toISOString(),
  error: result.error || null
} }];

const data = $('7. Normalize Delivery Result').first().json;
const idempotencyKey = 'follow-up:' + data.executionId + ':' + data.stepId;
return [{ json: {
  ...data,
  idempotencyKey: idempotencyKey,
  preparedAt: new Date().toISOString()
} }];
